INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (93, 170, 'Double sides adhesive tape jumbo rolls', '../upload/image/20180826/20180826130518_50410.jpg', '<p></p><p>Double sides adhesive tape jumbo rolls</p> <p>Product Name: hot melt double-sided tape<br/> Double sides adhesive tape jumbo rolls consists of:<br/> Release: release paper<br/> A surface adhesive: hot melt adhesive<br/> Substrate: tissue paper<br/> B surface adhesive: hot melt adhesive<br/> Physical properties:<br/> Total thickness: PET basic:30,80,90,100,120UM,150UM,190UM ....<br/> Tissue basic: 60,100,80,160 UM...<br/> initial tack&gt; 8<br/> 180 degree peel force (the stainless steel plate)&gt; 1.1kg/25mm<br/> holding force of&gt; 10hrs<br/> tensile strength&gt; 7N/cm<br/> The above data is based on<br/> BOPP packing tape finished rolls , masking tape and double sides adhesive tape finished rolls ,smaller rolls<br/> GB4852-84, GB-2792-81, GB-7753-84 test method to detect reliable test results<br/> But does not represent the guaranteed value of the product, due to environmental changes, the test results may vary, the numerical deviation 5%, mass production and the use of bigger and then Try qualified.<br/> Characteristics and Uses:<br/> Senior white tissue paper substrate, solvent-based polyacrylate adhesive coated both sides covered, then covered with easy to peel the timber is made of;<br/> Good initial tack and adhesion good, and easy to use cold resistance, good heat resistance; the plastic surface equatorial good; apply to leather, gift wrap and footwear adhesive stickers, stationery, office</p>', '2026-09-06 20:58:45');